import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    const [message, setMessage] = React.useState('Выберите действие в меню пользователя.');
    return <div className="dsusermenu-example">
    <style>{exampleStyles}</style>
    <div className="demo-stack">
    <div style={{ minHeight: 260, display: 'flex', alignItems: 'flex-start', justifyContent: 'flex-end', padding: 8, background: 'var(--ds-header-bg)' }}>
    <S.DsUserMenu name={'Анна Иванова'} email={'a.ivanova@example.com'} items={[{ id: 'p', label: 'Профиль' }, { id: 'l', label: 'Язык' }, { divider: true }, { id: 'x', label: 'Выйти', icon: 'exit_to_app' }]} onSelect={item => setMessage('Выбрано: ' + item.label)}/>
    </div>
    <p role="status" aria-label="Результат выбора">{message}</p>
    </div>
    </div>;
}

const exampleStyles = ".dsusermenu-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsusermenu-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsusermenu-example p{margin:0}\n";

export { App as Example };
